/**
 * Utility functions for user-defined workflow variables (Homey-style).
 *
 * Used by AdvancedWorkflowVariables panel and unit tests.
 */
import { uid } from 'quasar';
import type { WorkflowVariable } from '../workflow-advanced-models';

export type VarType = 'text' | 'number' | 'boolean' | 'document';

export interface VariableGroup {
  type: VarType;
  label: string;
  icon: string;
  color: string;
  variables: WorkflowVariable[];
}

export interface TypeConfig {
  icon: string;
  color: string;
  label: string;
}

/**
 * Type configurations for workflow variables.
 * Each type defines an icon (Material Design name), color theme, and display label.
 *
 * Document type: Stores a document reference that can be passed between workflows.
 * Values are set automatically via the ACTION_LOGIC_SET_DOCUMENT_VAR card.
 */
const TYPE_CONFIGS: Record<VarType, TypeConfig> = {
  text: { icon: 'text_fields', color: 'blue', label: 'Text' },
  number: { icon: 'pin', color: 'green', label: 'Number' },
  boolean: { icon: 'toggle_on', color: 'orange', label: 'Yes/No' },
  document: { icon: 'description', color: 'purple', label: 'Document' },
};

/** Ordered list of types for consistent display. */
const TYPE_ORDER: VarType[] = ['text', 'number', 'boolean', 'document'];

/**
 * Get icon, color, and label for a variable type.
 */
export function getTypeConfig(type: VarType): TypeConfig {
  return TYPE_CONFIGS[type] || TYPE_CONFIGS.text;
}

/**
 * Group variables by type in a fixed order (text, number, boolean, document).
 * Empty groups are omitted.
 */
export function groupWorkflowVariables(variables: WorkflowVariable[]): VariableGroup[] {
  const groups: VariableGroup[] = [];

  for (const type of TYPE_ORDER) {
    const vars = variables.filter(v => v.var_type === type);
    if (vars.length > 0) {
      const cfg = TYPE_CONFIGS[type];
      groups.push({
        type,
        label: cfg.label,
        icon: cfg.icon,
        color: cfg.color,
        variables: vars.sort((a, b) => a.name.localeCompare(b.name)),
      });
    }
  }

  return groups;
}

/**
 * Filter groups so only variables matching `search` by name survive.
 * Empty groups are removed.
 */
export function filterWorkflowVariables(groups: VariableGroup[], search: string): VariableGroup[] {
  if (!search) return groups;
  const term = search.toLowerCase();
  return groups
    .map(group => ({
      ...group,
      variables: group.variables.filter(v => v.name.toLowerCase().includes(term)),
    }))
    .filter(group => group.variables.length > 0);
}

/**
 * Create a new WorkflowVariable with a generated UUID.
 */
export function createVariable(
  name: string,
  varType: VarType,
  defaultValue: string | number | boolean | null,
): WorkflowVariable {
  return {
    id: uid(),
    name: name.trim(),
    var_type: varType,
    default_value: defaultValue,
    value: defaultValue,
  };
}

/**
 * Validate a variable name. Returns an error string or null if valid.
 */
export function validateVariableName(
  name: string,
  existing: WorkflowVariable[],
  excludeId?: string,
): string | null {
  const trimmed = name.trim();
  if (!trimmed) return 'variable_name_required';
  if (existing.some(v => v.name === trimmed && v.id !== excludeId)) {
    return 'variable_name_duplicate';
  }
  return null;
}

/**
 * Get the display value of a variable (value or default_value).
 */
export function getVariableDisplayValue(variable: WorkflowVariable): string {
  const val = variable.value ?? variable.default_value;
  if (val === null || val === undefined) return '';
  if (typeof val === 'boolean') return val ? 'Yes' : 'No';
  return String(val);
}
